export const US_STATES=['Alabama','Alaska','Arizona','Arkansas','California','Colorado','Connecticut','Delaware','District of Columbia','Florida','Georgia','Hawaii','Idaho','Illinois','Indiana','Iowa','Kansas','Kentucky','Louisiana','Maine','Maryland','Massachusetts','Michigan','Minnesota','Mississippi','Missouri','Montana','Nebraska','Nevada','New Hampshire','New Jersey','New Mexico','New York','North Carolina','North Dakota','Ohio','Oklahoma','Oregon','Pennsylvania','Rhode Island','South Carolina','South Dakota','Tennessee','Texas','Utah','Vermont','Virginia','Washington','West Virginia','Wisconsin','Wyoming'];
export const USM_APPLICATIONS={review:'Değerlendirilecek',eligible:'Başvurulabilir',conditional:'Koşullu / teyit gerekli',ineligible:'Uygun değil',applied:'Başvuruldu',closed:'Başvuru kapalı'};
const cityOf=p=>p.city||((p.location||'').includes(',')?p.location.split(',')[0].trim():'');
const placeOf=p=>[p.usState,cityOf(p)].filter(Boolean).join(' / ')||'Konum teyit gerekli';

export function mergeUSAgriPrograms(saved=[]){const edits=new Map(saved.map(p=>[p.id,p]));return [...US_AGRI_MASTERS.map(p=>({...p,country:'ABD',application:'review',description:p.content,duration:p.duration||'',notes:'',researchNotes:p.researchNotes||'',programUrl:p.programUrl||p.sources[0]?.[1]||'',applicationUrl:p.applicationUrl||p.sources[1]?.[1]||'',...edits.get(p.id),usState:p.usState||'',city:cityOf(p),location:p.location||''})),...saved.filter(p=>p.custom&&!US_AGRI_MASTERS.some(b=>b.id===p.id)).map(p=>({school:'',program:'',country:'ABD',usState:'',application:'review',description:'',duration:'',notes:'',researchNotes:'',location:'',area:'',format:'',entry:'',transition:'',timing:'',contact:'',programUrl:'',applicationUrl:'',sources:[],...p,city:cityOf(p)}))].filter(p=>!p.deleted).sort((a,b)=>a.school.localeCompare(b.school,'tr')||a.program.localeCompare(b.program,'tr'));}
export function usMasterFilters(params){const usState=(params.get('usState')||'all').slice(0,100),application=params.get('usa')||'all';return {usState,city:(params.get('usCity')||'all').slice(0,100),application:application==='all'||USM_APPLICATIONS[application]?application:'all'};}
export function filterUSAgriPrograms(records,f){return records.filter(p=>(f.usState==='all'||p.usState===f.usState)&&(!f.city||f.city==='all'||cityOf(p)===f.city)&&(f.application==='all'||p.application===f.application));}
export function usAgricultureMastersHref(id,options={}){return '#'+new URLSearchParams({view:'route',route:'agriculture',study:'us-masters',...(id?{fromCard:id}:{}),...(options.usState&&options.usState!=='all'?{usState:options.usState}:{}),...(options.city&&options.city!=='all'?{usCity:options.city}:{}),...(options.application&&options.application!=='all'?{usa:options.application}:{}),...(options.programId?{program:options.programId}:{})});}
export function isUSAgricultureMasterCard(card){const title=card.title.toLocaleLowerCase('tr').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/[^a-z0-9]+/g,' ').trim();return title==='amerikada master agriculture';}
const options=(values,current)=>Object.entries(values).map(([v,t])=>`<option value="${esc(v)}"${v===current?' selected':''}>${esc(t)}</option>`).join('');
function select(p,key,label,values){return `<label class="usm-select-label"><span>${label}</span><select data-usm-edit="${key}" data-id="${esc(p.id)}" class="job-tag ${key==='usState'?'job-country':'job-application'}" aria-label="${label}">${options(values,p[key])}</select></label>`;}
function edit(p,key,label,rows=2,scope='quick'){const id='usm-'+scope+'-'+p.id+'-'+key;return `<label class="usm-edit-field" for="${id}"><span>${label}</span><textarea id="${id}" data-usm-edit="${key}" data-id="${esc(p.id)}" rows="${rows}" maxlength="${key==='notes'?20000:50000}" placeholder="${label} yaz…">${esc(p[key])}</textarea></label>`;}
function input(p,key,label,type='text'){const id='usm-full-'+p.id+'-'+key;return `<label class="usm-edit-field" for="${id}"><span>${label}</span><input id="${id}" type="${type}" data-usm-edit="${key}" data-id="${esc(p.id)}" value="${esc(p[key])}" maxlength="${type==='url'?4000:500}"></label>`;}
function link(url,label){try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol)||u.username||u.password)return '';}catch{return '';}return `<a class="button quiet" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;}
const states=()=>({'':'Eyalet seç',...Object.fromEntries(US_STATES.map(s=>[s,s]))});

export const USM_INFO_FIELDS=['school','program','application','area','duration','programUrl','applicationUrl','description','format','entry','transition','timing','contact','researchNotes'];
export function createUSMasterDraft(program){return Object.fromEntries(USM_INFO_FIELDS.map(k=>[k,program[k]??'']));}
const TABS={overview:'Açıklama',program:'Program bilgisi',requirements:'Gereklilikler'};
function readBlock(label,value){return `<section class="usm-read-block"><h3>${label}</h3><p>${esc(value||'Henüz eklenmedi.')}</p></section>`;}
function draftField(p,key,label,rows=0){const id='usm-draft-'+p.id+'-'+key;return `<label class="usm-edit-field" for="${id}"><span>${label}</span>${rows?`<textarea id="${id}" rows="${rows}" data-usm-draft="${key}" data-id="${esc(p.id)}" maxlength="50000">${esc(p[key])}</textarea>`:`<input id="${id}" type="${key.endsWith('Url')?'url':'text'}" value="${esc(p[key])}" data-usm-draft="${key}" data-id="${esc(p.id)}" maxlength="${key.endsWith('Url')?4000:500}">`}</label>`;}
function tabContent(p,tab,editing){
 if(tab==='overview')return editing?`<div class="usm-quick-fields">${draftField(p,'school','Üniversite')}${draftField(p,'program','Program adı')}</div>${draftField(p,'description','Açıklama',4)}`:readBlock('Açıklama',p.description);
 if(tab==='program')return editing?`<div class="usm-quick-fields">${draftField(p,'duration','Süre / kaç yıl')}${readBlock('Eyalet / şehir',placeOf(p))}${draftField(p,'area','Alan / uzmanlaşma')}${draftField(p,'programUrl','Program bağlantısı')}${draftField(p,'applicationUrl','Başvuru bağlantısı')}</div>${draftField(p,'format','Eğitim yapısı / ücret / finansman',3)}${draftField(p,'timing','Başvuru tarihleri',2)}${draftField(p,'contact','İletişim',2)}`:`<div class="usm-facts"><div><small>Süre</small><strong>${esc(p.duration||'Henüz eklenmedi')}</strong></div><div><small>Konum</small><strong>${esc(p.location||p.usState||'Henüz eklenmedi')}</strong></div><div><small>Alan</small><strong>${esc(p.area||'Henüz eklenmedi')}</strong></div></div>${readBlock('Eğitim yapısı / ücret / finansman',p.format)}${readBlock('Başvuru tarihleri',p.timing)}${readBlock('İletişim',p.contact)}`;
 return editing?`${draftField(p,'entry','Kabul koşulları / GPA / dil / belgeler',4)}${draftField(p,'transition','Alan değişimi / uygunluk',3)}${draftField(p,'researchNotes','Ek araştırma ve kaynak notları',3)}`:`${readBlock('Kabul koşulları / GPA / dil / belgeler',p.entry)}${readBlock('Alan değişimi / uygunluk',p.transition)}${p.researchNotes?readBlock('Ek araştırma ve kaynak notları',p.researchNotes):''}${p.sources?.length?`<details class="usm-source-archive"><summary>Resmî kaynaklar · Kasım 2026</summary>${p.sources.map(([title,url,summary])=>`<article class="source-note">${link(url,esc(title))}<p>${esc(summary)}</p></article>`).join('')}</details>`:''}`;
}
export function renderUSAgricultureMasters(fromCard=null,saved=[],filters={usState:'all',application:'all'},opened=new Set(),ui={}){
 const all=mergeUSAgriPrograms(saved),rows=filterUSAgriPrograms(all,filters),usedStates=[...new Set(all.map(p=>p.usState).filter(Boolean))].sort(),usedCities=[...new Set(all.filter(p=>filters.usState==='all'||p.usState===filters.usState).map(cityOf).filter(Boolean))].sort(),usedCountries=[...new Set(all.map(p=>p.country||'ABD'))].sort(),onlyUS=usedCountries.every(c=>['abd','usa','us','united states','united states of america','amerika','amerika birleşik devletleri'].includes(c.toLocaleLowerCase('tr').trim()));
 return `<nav class="route-trail" aria-label="Yol içinde gezinme"><a href="#view=route&route=agriculture">Tarım ve hayvancılık</a><span>›</span><span>${onlyUS?'ABD tarım masterları':'Tarım masterları'}</span></nav><section class="job-heading"><div><span class="eyebrow">${onlyUS?'EĞİTİM / YALNIZ ABD':'EĞİTİM / TARIM'}</span><h1>${onlyUS?'Amerika’da tarım masterları':'Tarım masterları'}</h1><p>Ranch yönetimi ve hassas hayvancılık odaklı master yolları. Bir satırı açarak ayrıntıları ve kaynakları incele.</p></div><div class="job-header-actions"><a class="button quiet" href="#view=route&route=agriculture">Kartlarıma dön →</a>${fromCard?`<a class="button quiet" href="#view=route&route=agriculture&card=${encodeURIComponent(fromCard)}">Bu kartın notları</a>`:''}</div></section><form id="usm-add-form" class="job-add-form usm-add-inline"><label class="job-query-label" for="usm-new-school"><span>Üniversite adı</span><input id="usm-new-school" maxlength="300" placeholder="Üniversite adı" required></label><label class="job-query-label" for="usm-new-program"><span>Program adı</span><input id="usm-new-program" maxlength="500" placeholder="Örn. Agriculture MS" required></label><label class="job-query-label" for="usm-new-state"><span>Eyalet / bölge</span><input id="usm-new-state" list="usm-state-suggestions" maxlength="100" placeholder="Eyalet yaz veya seç" autocomplete="off"><datalist id="usm-state-suggestions">${usedStates.map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist></label><label class="job-query-label" for="usm-new-city"><span>Şehir</span><input id="usm-new-city" maxlength="100" placeholder="Kampüs şehri"></label><label class="job-filter-label" for="usm-new-application"><span>Başvuru durumu</span><select id="usm-new-application" class="job-filter-select">${options(USM_APPLICATIONS,'review')}</select></label><button class="button primary" type="submit">+ Program ekle</button></form><section class="job-filters usm-filters" aria-label="ABD master filtreleri"><label class="job-filter-label"><span>Eyalet</span><select id="usm-filter-state" class="job-filter-select" data-usm-filter>${options({all:'Tüm eyaletler',...Object.fromEntries(usedStates.map(s=>[s,s]))},filters.usState)}</select></label><label class="job-filter-label"><span>Şehir</span><select id="usm-filter-city" class="job-filter-select" data-usm-filter>${options({all:'Tüm şehirler',...Object.fromEntries(usedCities.map(c=>[c,c]))},filters.city||'all')}</select></label><label class="job-filter-label"><span>Başvuru durumu</span><select id="usm-filter-application" class="job-filter-select" data-usm-filter>${options({all:'Tüm durumlar',...USM_APPLICATIONS},filters.application)}</select></label><a class="button quiet" href="${usAgricultureMastersHref(fromCard)}">Filtreleri temizle</a></section><div class="job-results-head"><p role="status"><strong>${rows.length}</strong> / ${all.length} program</p><span>Üniversite adına göre A–Z</span></div><div class="master-list" role="region" aria-label="ABD tarım masterları listesi" tabindex="0">${rows.map(savedProgram=>{
  const draft=ui.drafts?.get(savedProgram.id),editing=!!draft,p={...savedProgram,...draft,notes:savedProgram.notes},tab=ui.tabs?.get(p.id)||'overview';
  return `<details class="master-row usm-row" data-usm-details="${esc(p.id)}"${opened.has(p.id)?' open':''}><summary><span class="master-row-main"><strong>${esc(p.school)}</strong><span>${esc(p.program)}</span></span><span class="master-row-tags"><span class="usm-place"><small>Eyalet / şehir</small><span>${esc(placeOf(p))}</span></span>${select(p,'application','Başvuru durumu',USM_APPLICATIONS)}<span class="master-fold" aria-hidden="true">+</span></span></summary><div class="usm-quick"><div class="usm-tabs" role="tablist" aria-label="${esc(savedProgram.school)} bilgi sekmeleri">${Object.entries(TABS).map(([id,title])=>`<button id="usm-tab-${esc(p.id)}-${id}" class="usm-tab" role="tab" aria-selected="${id===tab}" aria-controls="usm-tabpanel-${esc(p.id)}" data-action="usm-tab" data-id="${esc(p.id)}" data-tab="${id}">${title}</button>`).join('')}<div class="usm-edit-actions">${editing?`<button class="button quiet usm-save" data-action="usm-save" data-id="${esc(p.id)}" aria-label="Bilgileri kaydet" title="Kaydet">✓</button><button class="button quiet" data-action="usm-cancel" data-id="${esc(p.id)}" aria-label="Düzenlemeden vazgeç" title="Vazgeç">×</button><button class="button quiet usm-delete" data-action="usm-delete" data-id="${esc(p.id)}" aria-label="Programı sil">Delete</button><small>Bilgiler düzenleniyor</small>`:`<button class="button quiet" data-action="usm-edit" data-id="${esc(p.id)}" aria-label="Bilgileri düzenle" title="Bilgileri düzenle">✎</button>`}</div><div class="usm-links">${link(savedProgram.programUrl,'Program sayfası')}${link(savedProgram.applicationUrl,'Başvuru / kabul sayfası')}</div></div><div class="usm-inline-layout"><div class="usm-tab-content" id="usm-tabpanel-${esc(p.id)}" role="tabpanel" aria-labelledby="usm-tab-${esc(p.id)}-${tab}"><p class="usm-location">${esc(savedProgram.location||savedProgram.usState||'Konum eklenmedi')}</p>${tabContent(p,tab,editing)}</div><aside class="usm-always-notes">${edit(savedProgram,'notes','Not',4)}<small>Notların otomatik kaydedilir.</small></aside></div></div></details>`;
 }).join('')||'<div class="empty-state">Bu filtrelerde program bulunamadı.</div>'}</div><p class="master-scope">Notların otomatik kaydedilir. Diğer bilgileri kalemle düzenle, ✓ ile kaydet veya × ile vazgeç.</p>`;
}
export function renderUSAgriMasterDetail(){return '';}
